  "response": "<solution>\nimport numpy as np\nimport matplotlib.pyplot as plt\nimport random\n\n# Constants\nNUMBERS = list(range(1, 7))  # Adjusting for dice rolls (1 to 6)\n\ndef task_func(rolls, seed=None):\n    \"\"\"\n    Simulate dice rolls, compute outcome frequencies, and plot a histogram.\n\n    Args:\n        rolls (int): Number of dice rolls to simulate.\n        seed (optional): Seed for reproducible random results.\n\n    Returns:\n        tuple: (frequency_array, histogram_axes)\n    \"\"\"\n    if isinstance(rolls, bool) or not isinstance(rolls, (int, np.integer)):\n        raise TypeError(\"rolls must be a non-negative integer\")\n    if rolls < 0:\n        raise ValueError(\"rolls must be non-negative\")\n\n    rolls = int(rolls)\n    \n    # Use a localized Random instance if seed is provided, \n    # otherwise fallback to global random to respect globally set seeds.\n    if seed is not None:\n        rng = random.Random(seed)\n    else:\n        rng = random\n\n    # Use a numpy array of dtype=int to prevent np.bincount from raising a TypeError when rolls=0\n    results = np.array([rng.choice(NUMBERS) for _ in range(rolls)], dtype=int)\n    frequency = np.bincount(results, minlength=7)[1:7]\n\n    fig, ax = plt.subplots()\n    ax.hist(results, bins=np.arange(0.5, 7.5, 1), edgecolor=\"black\")\n    ax.set_title(\"Histogram of Dice Rolls\")\n    ax.set_xlabel(\"Dice Value\")\n    ax.set_ylabel(\"Frequency\")\n    ax.set_xticks(NUMBERS)\n\n    return frequency, ax\n</solution>",
